import re
import sqlite3
from datetime import datetime
from pathlib import Path


PROJECT_ID = "PRJ-SZ-25HS-主体-001"
TARGET_CHECKPOINT = "CHK-SZ25-003"
EXPECTED_REASON = "王泽明签字、建设施工监理三方公章及日期须全部完整后方可销项"
