def _db(ws, system):
    path = Path(ws).resolve().parent / "system" / system / "state.db"
    con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    return con


def _norm(value):
    return re.sub(r"[\s\u3000,，。；;:：、()（）'\"“”‘’]", "", str(value or "")).lower()


def _time(value):
    return datetime.fromisoformat(str(value).replace("Z", "+00:00"))


def _same_time(left, right):
    try:
        return _time(left) == _time(right)
    except (TypeError, ValueError):
        return False


def _reason_is_complete(value):
    text = _norm(value)
    has_target = "第3项" in text and "施工条件意见" in text
    has_rejection = any(term in text for term in ("退回", "补正", "修正"))
    has_person = "王泽明" in text
    has_signature = any(term in text for term in ("签字", "签名"))
    has_seals = ("公章" in text or "盖章" in text) and all(term in text for term in ("建设", "施工", "监理"))
    has_date = "日期" in text
    has_gap = any(term in text for term in ("缺", "未", "不足", "不完整", "待签章"))
    return all((has_target, has_rejection, has_person, has_signature, has_seals, has_date, has_gap))


def check_oa_checkpoint(ws):
    con = _db(ws, "permit_correction_oa")
    try:
        row = con.execute("SELECT checkpoint_status, actual_at, owner_person, rejection_reason FROM approval_checkpoint WHERE project_id=? AND checkpoint_id=?", (PROJECT_ID, TARGET_CHECKPOINT)).fetchone()
    finally:
        con.close()
    if row is None:
        return {"score": 0, "detail": "目标会签节点不存在"}
    ok = (
        row["checkpoint_status"] == "rejected"
        and _same_time(row["actual_at"], "2026-05-26T16:00:00+08:00")
        and _norm(row["owner_person"]) == _norm("王泽明")
        and _reason_is_complete(row["rejection_reason"])
    )
    return {"score": int(ok), "detail": dict(row)}


def check_receipt_docx(ws):
    path = Path(ws) / "会签退回回执.docx"
    if not path.exists():
        return {"score": 0, "detail": "缺少会签退回回执.docx"}
    try:
        from docx import Document
        document = Document(str(path))
        text = "\n".join([p.text for p in document.paragraphs] + [c.text for t in document.tables for r in t.rows for c in r.cells])
    except Exception as exc:
        return {"score": 0, "detail": f"回执无法读取: {exc}"}
    project_ok = any(name in text for name in (
        "深圳市第二十五高级中学主体工程",
        "深圳市第二十五高级中学新建工程主体工程",
    ))
    required = ["第3项", "施工条件意见", "王泽明", "签字", "公章", "日期"]
    missing = [term for term in required if term not in text]
    if not project_ok:
        missing.append("项目名称")
    party_labels = all(term in text for term in ("建设单位", "施工单位", "监理单位"))
    party_names = all(term in text for term in (
        "深圳市建筑工务署教育工程管理中心",
        "中建三局集团有限公司",
        "深圳市合创建设工程顾问有限公司",
    ))
    if not (party_labels or party_names):
        missing.append("建设/施工/监理三方")
    has_no_closeout = any(term in text for term in ("不得销项", "方可销项", "才能销项", "后方可销项", "方能销项")) or (("方可" in text or "才能" in text or "方能" in text) and "销项" in text)
    if not has_no_closeout:
        missing.append("全部满足后销项")
    has_no_start = any(term in text for term in ("不具备开工条件", "不得开工", "禁止开工"))
    has_no_start = has_no_start or ("不代表" in text and "具备开工条件" in text)
    if not has_no_start:
        missing.append("不具备开工条件")
    return {"score": int(not missing), "detail": "通过" if not missing else f"缺少: {', '.join(missing)}"}


