            and action is not None
            and dict(action) == {"action_status": "in_progress", "completed_at": None, "responsible_person": "王泽明"}
            and package is not None
            and dict(package) == {"signoff_status": "pending", "package_status": "locked", "submitted_at": None}
        )
    finally:
        oa.close(); checklist.close()
    return {"score": int(ok), "detail": "相关非目标后态保持不变" if ok else "相关非目标后态发生变化"}


def check_untouched_source_files(ws):
    root = Path(ws)
    changed = []
    for name, expected in SOURCE_HASHES.items():
        path = root / name
        if not path.exists() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            changed.append(name)
    return {"score": int(not changed), "detail": "原始材料未被改写" if not changed else f"被改写: {changed}"}
